window.JS_BRIDGE_DEMO = {"version":1,"files":{"project.godot":"; Engine configuration file.\n; It's best edited using the editor UI and not directly,\n; since the parameters that go here are not all obvious.\n\nconfig_version=5\n\n[application]\n\nconfig/name=\"JS Bridge Demo\"\nconfig/description=\"Import and call JavaScript ES modules from GDScript via JavaScriptBridge (web builds).\"\nrun/main_scene=\"res://main.tscn\"\nconfig/features=PackedStringArray(\"4.7\", \"GL Compatibility\")\n\n[rendering]\n\nrenderer/rendering_method=\"gl_compatibility\"\nrenderer/rendering_method.mobile=\"gl_compatibility\"\n","main.tscn":"[gd_scene load_steps=2 format=3]\n\n[ext_resource type=\"Script\" path=\"res://main.gd\" id=\"1_main\"]\n\n[node name=\"Main\" type=\"Control\"]\nlayout_mode = 3\nanchors_preset = 15\nanchor_right = 1.0\nanchor_bottom = 1.0\ngrow_horizontal = 2\ngrow_vertical = 2\nscript = ExtResource(\"1_main\")\n\n[node name=\"Margin\" type=\"MarginContainer\" parent=\".\"]\nlayout_mode = 1\nanchors_preset = 15\nanchor_right = 1.0\nanchor_bottom = 1.0\ngrow_horizontal = 2\ngrow_vertical = 2\ntheme_override_constants/margin_left = 18\ntheme_override_constants/margin_top = 18\ntheme_override_constants/margin_right = 18\ntheme_override_constants/margin_bottom = 18\n\n[node name=\"Root\" type=\"VBoxContainer\" parent=\"Margin\"]\nlayout_mode = 2\ntheme_override_constants/separation = 10\n\n[node name=\"Title\" type=\"Label\" parent=\"Margin/Root\"]\nlayout_mode = 2\ntheme_override_font_sizes/font_size = 30\ntext = \"JS Bridge Demo\"\n\n[node name=\"Sub\" type=\"Label\" parent=\"Margin/Root\"]\nlayout_mode = 2\ntheme_override_colors/font_color = Color(1, 1, 1, 0.6)\ntheme_override_font_sizes/font_size = 14\ntext = \"Calls a JavaScript ES module from GDScript via JavaScriptBridge. The helpers live in window.GodotJs (see godotjs_module.js). Press F5 to run.\"\nautowrap_mode = 2\n\n[node name=\"StatusLabel\" type=\"Label\" parent=\"Margin/Root\"]\nlayout_mode = 2\ntheme_override_colors/font_color = Color(0.55, 0.85, 1, 1)\ntheme_override_font_sizes/font_size = 14\ntext = \"Press F5 to play this scene in the web editor.\"\n\n[node name=\"BtnEval\" type=\"Button\" parent=\"Margin/Root\"]\nlayout_mode = 2\nfocus_mode = 0\ntext = \"1. eval() a JS expression\"\n\n[node name=\"BtnBridge\" type=\"Button\" parent=\"Margin/Root\"]\nlayout_mode = 2\nfocus_mode = 0\ntext = \"2. Call window.GodotJs from GDScript\"\n\n[node name=\"BtnStore\" type=\"Button\" parent=\"Margin/Root\"]\nlayout_mode = 2\nfocus_mode = 0\ntext = \"3. localStorage round-trip through JS\"\n\n[node name=\"BtnImport\" type=\"Button\" parent=\"Margin/Root\"]\nlayout_mode = 2\nfocus_mode = 0\ntext = \"4. Dynamically import an ES module\"\n\n[node name=\"BtnFetch\" type=\"Button\" parent=\"Margin/Root\"]\nlayout_mode = 2\nfocus_mode = 0\ntext = \"5. Async fetch() with poll\"\n\n[node name=\"OutLabel\" type=\"Label\" parent=\"Margin/Root\"]\nlayout_mode = 2\nsize_flags_vertical = 3\ntheme_override_colors/font_color = Color(1, 0.88, 0.54, 1)\ntheme_override_font_sizes/font_size = 15\ntext = \"Output appears here.\"\nautowrap_mode = 2\n\n[node name=\"Hint\" type=\"Label\" parent=\"Margin/Root\"]\nlayout_mode = 2\ntheme_override_colors/font_color = Color(1, 1, 1, 0.4)\ntheme_override_font_sizes/font_size = 12\ntext = \"JavaScriptBridge only exists in web builds. On desktop export these buttons explain that instead of crashing.\"\nautowrap_mode = 2\n","main.gd":"extends Control\n\n# JS Bridge Demo - call a JavaScript ES module from GDScript.\n#\n# Pattern (web builds only):\n#   1. Sync calls: JavaScriptBridge.eval(\"...\") or\n#      JavaScriptBridge.get_interface(\"GodotJs\").someFunction(args).\n#   2. Async work (import(), fetch()): start it with one eval, then poll a\n#      field the JS side fills in when done (eval is synchronous, so a plain\n#      `await import(...)` inside eval cannot return the module).\n#\n# window.GodotJs is defined by the page hosting the game. In this web editor\n# it is built into the page; in your own exported HTML shell, copy the\n# matching source from godotjs_module.js into a <script> tag.\n\nconst DATA_MODULE := \"data:text/javascript,export const answer = 42; export function triple(x) { return x * 3; }\"\nconst FETCH_URL := \"data:text/plain,hello from fetch\"\n\n@onready var status_label: Label = $Margin/Root/StatusLabel\n@onready var out_label: Label = $Margin/Root/OutLabel\n\n\nfunc _ready() -> void:\n\t$Margin/Root/BtnEval.pressed.connect(_on_eval)\n\t$Margin/Root/BtnBridge.pressed.connect(_on_bridge)\n\t$Margin/Root/BtnStore.pressed.connect(_on_store)\n\t$Margin/Root/BtnImport.pressed.connect(_on_import)\n\t$Margin/Root/BtnFetch.pressed.connect(_on_fetch)\n\tif _web():\n\t\tstatus_label.text = \"Running in a web build - the JS bridge is available.\"\n\telse:\n\t\tstatus_label.text = \"Not a web build - play this in the web editor (F5) to use the bridge.\"\n\n\nfunc _web() -> bool:\n\treturn OS.has_feature(\"web\")\n\n\nfunc _say(msg: String) -> void:\n\tout_label.text = msg\n\n\nfunc _need_web() -> bool:\n\tif _web():\n\t\treturn true\n\t_say(\"JavaScriptBridge only exists in web builds. Press F5 in the web editor to run this demo.\")\n\treturn false\n\n\nfunc _poll(expr: String, timeout: float) -> String:\n\tvar waited := 0.0\n\twhile waited < timeout:\n\t\tvar v = JavaScriptBridge.eval(expr)\n\t\tif v != null and str(v) != \"\":\n\t\t\treturn str(v)\n\t\tawait get_tree().create_timer(0.15).timeout\n\t\twaited += 0.15\n\treturn \"\"\n\n\nfunc _on_eval() -> void:\n\tif not _need_web():\n\t\treturn\n\tvar v = JavaScriptBridge.eval(\"({ greeting: 'hello from JS', answer: 6 * 7, lang: navigator.language })\")\n\t_say(\"eval() returned: \" + JSON.stringify(v))\n\n\nfunc _on_bridge() -> void:\n\tif not _need_web():\n\t\treturn\n\tvar bridge = JavaScriptBridge.get_interface(\"GodotJs\")\n\tif bridge == null:\n\t\t_say(\"window.GodotJs was not found on this page.\")\n\t\treturn\n\tvar hello = bridge.hello(\"Godot\")\n\tvar total = bridge.add(19, 23)\n\tvar info = bridge.pageInfo()\n\t_say(\"hello() = \" + str(hello) + \" | add(19, 23) = \" + str(total) + \" | page = \" + str(info))\n\n\nfunc _on_store() -> void:\n\tif not _need_web():\n\t\treturn\n\tvar bridge = JavaScriptBridge.get_interface(\"GodotJs\")\n\tif bridge == null:\n\t\t_say(\"window.GodotJs was not found on this page.\")\n\t\treturn\n\tbridge.localSet(\"js_bridge_demo\", \"clicked@\" + str(int(Time.get_unix_time_from_system())))\n\tvar back = bridge.localGet(\"js_bridge_demo\")\n\tbridge.localRemove(\"js_bridge_demo_gone\")\n\t_say(\"wrote then read localStorage key 'js_bridge_demo' = \" + str(back))\n\n\nfunc _on_import() -> void:\n\tif not _need_web():\n\t\treturn\n\t_say(\"importing ES module...\")\n\tJavaScriptBridge.eval(\"GodotJs.importModule(\" + JSON.stringify(DATA_MODULE) + \")\")\n\tvar raw := await _poll(\"GodotJs.lastImport != null ? GodotJs.lastImport : ''\", 8.0)\n\tif raw == \"\":\n\t\tvar err = JavaScriptBridge.eval(\"GodotJs.lastImportError || 'timed out'\")\n\t\t_say(\"import failed: \" + str(err))\n\t\treturn\n\tvar tripled = JavaScriptBridge.eval(\"GodotJs.callExport('triple', 14)\")\n\tvar answer = JavaScriptBridge.eval(\"GodotJs.readExport('answer')\")\n\t_say(\"module: \" + raw + \" | triple(14) = \" + str(tripled) + \" | answer = \" + str(answer))\n\n\nfunc _on_fetch() -> void:\n\tif not _need_web():\n\t\treturn\n\t_say(\"fetching...\")\n\tJavaScriptBridge.eval(\"GodotJs.fetchText(\" + JSON.stringify(FETCH_URL) + \")\")\n\tvar raw := await _poll(\"GodotJs.lastFetch != null ? GodotJs.lastFetch : ''\", 8.0)\n\tif raw == \"\":\n\t\tvar err = JavaScriptBridge.eval(\"GodotJs.lastFetchError || 'timed out'\")\n\t\t_say(\"fetch failed: \" + str(err))\n\t\treturn\n\t_say(\"fetch() returned: \" + raw)\n","godotjs_module.js":"// godotjs_module.js - reference source for the page-side JS module used by\n// the JS Bridge Demo (main.gd). Two ways to use it:\n//\n// A) Inside THIS web editor: window.GodotJs is already defined by the page,\n//    so the demo works with F5 and no setup. Keep this file in sync with the\n//    page's copy if you change the helper names.\n//\n// B) In your own exported game: paste this file's helpers into your HTML\n//    shell inside a classic <script> tag before the engine boots:\n//      <script> window.GodotJs = { ...helpers below... }; </script>\n//    then call them from GDScript with:\n//      var bridge = JavaScriptBridge.get_interface(\"GodotJs\")\n//      var total = bridge.add(19, 23)\n//    Async work (import(), fetch()) cannot return through eval() because eval\n//    is synchronous: start it with one eval, then poll the `last*` field the\n//    helper fills in when the promise settles (see main.gd `_poll`).\n//\n// As a real ES module (bundlers / your own site code):\n//   import { hello, add } from \"./godotjs_module.js\";\n\nexport const BRIDGE_VERSION = 1;\n\nexport function hello(who) {\n\treturn \"hello, \" + who + \"!\";\n}\n\nexport function add(a, b) {\n\treturn Number(a) + Number(b);\n}\n\nexport function pageInfo() {\n\treturn (typeof navigator !== \"undefined\" ? navigator.language : \"?\") + \" @ \" +\n\t\t(typeof location !== \"undefined\" ? location.hostname : \"?\");\n}\n\nexport function localGet(key) {\n\ttry {\n\t\treturn window.localStorage.getItem(String(key));\n\t} catch (e) {\n\t\treturn null;\n\t}\n}\n\nexport function localSet(key, value) {\n\ttry {\n\t\twindow.localStorage.setItem(String(key), String(value));\n\t\treturn true;\n\t} catch (e) {\n\t\treturn false;\n\t}\n}\n\nexport function localRemove(key) {\n\ttry {\n\t\twindow.localStorage.removeItem(String(key));\n\t\treturn true;\n\t} catch (e) {\n\t\treturn false;\n\t}\n}\n\n// The async helpers below mirror the window.GodotJs object shape so the same\n// GDScript works against either. They keep module + result on a shared state\n// object because dynamic import() resolves asynchronously.\nexport var lastImport = null;\nexport var lastImportError = null;\nexport var lastModule = null;\nexport var lastFetch = null;\nexport var lastFetchError = null;\n\nexport function importModule(url) {\n\tlastImport = null;\n\tlastImportError = null;\n\tPromise.resolve().then(function () {\n\t\treturn import(url);\n\t}).then(function (mod) {\n\t\tlastModule = mod;\n\t\tvar info = {};\n\t\tvar keys = Object.keys(mod);\n\t\tfor (var i = 0; i < keys.length; i++) {\n\t\t\tinfo[keys[i]] = typeof mod[keys[i]];\n\t\t}\n\t\tlastImport = JSON.stringify(info);\n\t}).catch(function (err) {\n\t\tlastImportError = String(err);\n\t});\n\treturn \"loading\";\n}\n\nexport function callExport(name, arg) {\n\tif (!lastModule) {\n\t\treturn \"no-module\";\n\t}\n\tvar fn = lastModule[name];\n\tif (typeof fn !== \"function\") {\n\t\treturn \"not-a-function\";\n\t}\n\ttry {\n\t\treturn fn(arg);\n\t} catch (e) {\n\t\treturn \"error:\" + e;\n\t}\n}\n\nexport function readExport(name) {\n\tif (!lastModule) {\n\t\treturn \"no-module\";\n\t}\n\tvar v = lastModule[name];\n\tvar t = typeof v;\n\tif (t === \"number\" || t === \"string\" || t === \"boolean\") {\n\t\treturn v;\n\t}\n\treturn \"[\" + t + \"]\";\n}\n\nexport function fetchText(url) {\n\tlastFetch = null;\n\tlastFetchError = null;\n\tfetch(url).then(function (r) {\n\t\tif (!r.ok) {\n\t\t\tthrow new Error(\"HTTP \" + r.status);\n\t\t}\n\t\treturn r.text();\n\t}).then(function (t) {\n\t\tlastFetch = t;\n\t}).catch(function (err) {\n\t\tlastFetchError = String(err);\n\t});\n\treturn \"loading\";\n}\n"}};